    private const ROUTES=['/','/features','/playbills','/production-poster','/register','/register/manage'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}

    public static function render(string $route,string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$_SESSION['public_registration_csrf']??=bin2hex(random_bytes(24));
        if($_SERVER['REQUEST_METHOD']==='POST')self::handlePost($db,$route,$basePath);
        if($route==='/')self::landing($db,$basePath);
        if($route==='/features')self::features($basePath);
        if($route==='/playbills')self::playbills($db,$basePath);
        if($route==='/production-poster')self::productionPoster($db);
        if($route==='/register/manage')self::manage($db,$basePath);
        self::registration($db,$basePath);
    }

    private static function handlePost(PDO $db,string $route,string $basePath):never
    {
        if(!hash_equals((string)($_SESSION['public_registration_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your form session expired. Please try again.');self::redirect($basePath.($route==='/register/manage'?'/register/manage':'/register'));}
        try{
            if($route==='/register'){
                $slug=trim((string)($_POST['slug']??''));$opportunity=RegistrationService::opportunityBySlug($db,$slug,true);if(!$opportunity)throw new RuntimeException('Registration for that signup is not currently open in CTSMD Connect.');$result=RegistrationService::submit($db,$opportunity,$_POST,$basePath);$_SESSION['public_registration_success']=['title'=>$opportunity['title'],'status'=>$result['status'],'token'=>$result['token'],'type'=>$opportunity['opportunity_type'],'linked'=>(bool)($result['linked']??false)];self::redirect($basePath.'/register?submitted=1');
            }
            if($route==='/register/manage'){
                $token=(string)($_POST['token']??'');if(($_POST['action']??'')==='claim_audition'){$user=Auth::currentUser($db);if(!$user)throw new RuntimeException('Sign in to your verified CTSMD guardian account first.');AuditionIntakeBridge::claimWithToken($db,$token,(int)$user['id'],(int)($_POST['student_id']??0));self::flash('success','Audition linked to your child. Approved registrations move to casting as Under Review.');self::redirect($basePath.'/register/manage?token='.rawurlencode($token));}RegistrationService::cancelByToken($db,$token);self::flash('success','Registration cancelled.');self::redirect($basePath.'/register/manage?token='.rawurlencode($token));
            }
        }catch(RuntimeException $e){self::flash('error',$e->getMessage());$suffix=$route==='/register'?('?slug='.rawurlencode((string)($_POST['slug']??''))):('?token='.rawurlencode((string)($_POST['token']??'')));self::redirect($basePath.$route.$suffix);}
        self::redirect($basePath.'/');
    }

