    private static function landing(PDO $db,string $basePath):never
    {
        $opportunities=array_slice(RegistrationService::publicOpportunities($db),0,3);
        // Only deliberately announced basics. Never query casting, families or schedules here.
        $productions=$db->query("SELECT id,title,season,lifecycle_stage,audition_starts_at,audition_ends_at,performance_starts_at,performance_ends_at,EXISTS(SELECT 1 FROM production_artwork a WHERE a.production_id=productions.id AND a.role='poster') has_public_poster FROM productions WHERE announcement_published_at IS NOT NULL AND lifecycle_stage IN ('upcoming','planning','in_production','performing','completed','archived') ORDER BY COALESCE(performance_starts_at,audition_starts_at),id DESC LIMIT 40")->fetchAll();
        // Match the existing public Playbill/asset publication policy, including revocation.
        $playbills=$db->query("SELECT pb.production_id,pb.display_title,pb.subtitle,pb.public_slug,pb.artwork_stored_file_id,p.title production_title FROM playbills pb JOIN productions p ON p.id=pb.production_id WHERE pb.public_enabled=1 AND pb.editorial_status IN ('published','archived') AND pb.public_slug IS NOT NULL ORDER BY pb.published_at DESC,pb.id DESC LIMIT 40")->fetchAll();
        // Public landing displays explicitly published Playbills, independently of the
        // current-season production list. Public assets remain authorization checked.
        $artworks=[];
        foreach($playbills as $program){
            if(!$program['artwork_stored_file_id'])continue;
            $asset=PlaybillEnhancementService::publicAsset($db,(string)$program['public_slug'],'artwork',0);
            if($asset&&in_array($asset['mime_type'],['image/jpeg','image/png','image/webp'],true))$artworks[]=$program;
        }
        self::landingPage($basePath,OrganizationBranding::fromEnvironment(),$productions,$opportunities,$playbills,$artworks);
    }

