date['production_id']??0)===(int)$p['id']&&($candidate['opportunity_type']??'')==='audition'){$audition=$candidate;break;}}?><?php if($audition):?><a href="<?=self::u($basePath,'/register?slug='.rawurlencode($audition['slug']))?>"><?=$audition['is_full']?'Join audition waitlist':'Audition signup'?> ↗</a><?php else:?><a href="<?=self::u($basePath,'/productions/view?id='.(int)$p['id'])?>">Production details ↗</a><?php endif;?></div></article><?php endforeach;?></div></section><?php endif;?>
