    private static function registration(PDO $db,string $basePath):never
    {
        $success=$_SESSION['public_registration_success']??null;unset($_SESSION['public_registration_success']);$flash=$_SESSION['public_registration_flash']??null;unset($_SESSION['public_registration_flash']);$slug=trim((string)($_GET['slug']??''));$opportunity=$slug!==''?RegistrationService::opportunityBySlug($db,$slug,true):null;$opportunities=RegistrationService::publicOpportunities($db);
        $registeredChildren=[];$viewer=Auth::currentUser($db);
        if($opportunity&&$viewer&&!Auth::hasRole($viewer,'student')){
            $stmt=$db->prepare("SELECT u.id,CONCAT(u.first_name,' ',u.last_name) name,u.date_of_birth FROM family_relationships fr JOIN users u ON u.id=fr.student_user_id AND u.active=1 AND u.account_status<>'disabled' WHERE fr.guardian_user_id=:guardian AND fr.status='active' AND fr.relationship_type IN ('parent','guardian') ORDER BY u.first_name,u.last_name");
            $stmt->execute(['guardian'=>(int)$viewer['id']]);$registeredChildren=$stmt->fetchAll(PDO::FETCH_ASSOC);
        }
        self::head($opportunity?$opportunity['title']:'Auditions & signups',$basePath);?><main class="public-shell"><header class="public-header"><a class="public-brand" href="<?=self::u($basePath,'/')?>"><span>C</span><b>CTSMD <small>CONNECT</small></b></a><nav><a href="<?=self::u($basePath,'/join')?>">Create account</a><a href="<?=self::u($basePath,'/')?>">Home</a><a class="public-login" href="<?=self::u($basePath,'/login')?>">Member sign in</a></nav></header>
        <?php if($success):?><section class="registration-success"><small><?=$success['status']==='waitlisted'?'WAITLIST':'REGISTERED'?></small><h1><?=self::e($success['status']==='waitlisted'?'You’re on the waitlist.':'Registration received.')?></h1><p>We received the registration for <b><?=self::e($success['title'])?></b>. A confirmation email contains the private link needed to manage or cancel it.</p><?php if(($success['type']??'')==='audition'&&!empty($success['linked'])):?><p><strong>Linked to your child’s CTSMD Student account.</strong> CTSMD will use their recorded date of birth for any audition age restriction.</p><?php elseif(($success['type']??'')==='audition'):?><p>Already have a CTSMD account? Sign in and use the private link in your confirmation email to connect this audition to your child. New families can create and verify an account, add their child under My family, then link the original registration. You do not need to register again.</p><p><a href="<?=self::u($basePath,'/login')?>">Sign in</a> · <a href="<?=self::u($basePath,'/join')?>">Create account</a></p><?php endif;?><a href="<?=self::u($basePath,'/register')?>">Back to auditions & signups</a></section>
        <?php elseif($slug!==''&&!$opportunity):?><section class="registration-success"><small>REGISTRATION</small><h1>This signup is not currently available in CTSMD Connect.</h1><p>It may not have opened yet, may have closed, may no longer be published, or may be handled in CTSMD’s separate registration system.</p><a href="<?=self::u($basePath,'/register')?>">View open auditions & signups</a></section>
        <?php elseif($opportunity):?><div class="registration-layout"><section class="registration-info"><small><?=self::e(strtoupper($opportunity['opportunity_type']))?></small><h1><?=self::e($opportunity['title'])?></h1><p><?=self::e((string)$opportunity['summary'])?></p><?php if($opportunity['production_title']):?><dl><div><dt>Production</dt><dd><?=self::e($opportunity['production_title'])?></dd></div><?php if($opportunity['starts_at']):?><div><dt>When</dt><dd><?=self::e(date('M j, Y · g:i A',strtotime($opportunity['starts_at'])))?></dd></div><?php endif;?><?php if($opportunity['location']):?><div><dt>Where</dt><dd><?=self::e($opportunity['location'])?></dd></div><?php endif;?></dl><?php endif;?><?php if($opportunity['details']):?><div class="registration-details"><?=nl2br(self::e($opportunity['details']))?></div><?php endif;?></section><section class="registration-form-card"><?php if($flash):?><div class="public-flash <?=$flash['type']?>"><?=self::e($flash['message'])?></div><?php endif;?><header><small><?=$opportunity['is_full']?'WAITLIST':'REGISTRATION'?></small><h2><?=$opportunity['is_full']?'Join the waitlist':'Register'?></h2><p>We only ask for information needed to process this signup.</p></header><form method="post"><input type="hidden" name="csrf_token" value="<?=self::e((string)$_SESSION['public_registration_csrf'])?>"><input type="hidden" name="slug" value="<?=self::e($opportunity['slug'])?>">
          <?php if(IdentityRolePolicy::isAdult($db,Auth::userId()?:0)):?><p>You can register independently using your Adult Performer account details. Leave the child selector blank.</p><button type="submit" name="adult_self" value="1" formnovalidate>Register myself as an Adult participant</button><?php endif;?>
          <?php if(!empty($opportunity['production_id'])):$eligibility=$db->prepare('SELECT participant_category,student_minimum_age,student_maximum_age,participant_eligibility_date FROM productions WHERE id=?');$eligibility->execute([(int)$opportunity['production_id']]);$rules=$eligibility->fetch();?><p>Production participation: <?=self::e(['students'=>'Students only','adults'=>'Adults only','mixed'=>'Adults and Students'][$rules['participant_category']]??'Review required')?>. Student age limits: <?=$rules['student_minimum_age']===null?'no minimum':(int)$rules['student_minimum_age']?> / <?=$rules['student_maximum_age']===null?'no maximum':(int)$rules['student_maximum_age']?>. Eligibility date: <?=self::e($rules['participant_eligibility_date']?:'No age restriction date set')?>.</p><?php endif;?>
          <?php if($opportunity['minimum_age']!==null||$opportunity['maximum_age']!==null):?><p><strong>Age requirement:</strong> <?=$opportunity['minimum_age']!==null?'At least '.(int)$opportunity['minimum_age']:''?><?=$opportunity['minimum_age']!==null&&$opportunity['maximum_age']!==null?' and ':''?><?=$opportunity['maximum_age']!==null?'no older than '.(int)$opportunity['maximum_age']:''?> years, measured on <?=self::e((string)(PersonEligibility::cutoff($opportunity)?:'the published eligibility date'))?>. Registered children are checked using their saved date of birth. Guest ages are self-reported.</p><?php endif;?>
          <?php if($registeredChildren):?><label>Choose a child from your CTSMD household<select name="student_user_id" id="audition-student-select"><option value="">Register without selecting an account (guest)</option><?php foreach($registeredChildren as $child):?><option value="<?=(int)$child['id']?>"<?=!$child['date_of_birth']?' disabled':''?>><?=self::e((string)$child['name'])?><?=$child['date_of_birth']?'':' · add DOB in profile'?></option><?php endforeach;?></select><small>Selecting your child uses their saved date of birth and verified household identity. You do not need to enter an age.</small></label><?php endif;?>
          <div id="audition-guest-fields"><div class="field-pair"><label>Participant first name<input name="participant_first_name" maxlength="100" required></label><label>Participant last name<input name="participant_last_name" maxlength="100" required></label></div><label>Participant age on eligibility date<select name="participant_declared_age" required><option value="">Select exact age…</option><?php for($age=0;$age<=120;$age++):?><option value="<?=$age?>"><?=$age?><?=$age===120?' (120 maximum)':''?></option><?php endfor;?></select><small>For guests, this age is self-reported and is self-reported and used to check the minimum age. If you have a CTSMD Student account, select it above to use the recorded date of birth.</small></label><div class="field-pair"><label>Primary contact email<input type="email" name="registrant_email" required></label><label>Primary contact phone <span>optional</span><input name="registrant_phone" maxlength="40"></label></div><fieldset><legend>Parent / guardian contact</legend><p>Required when the participant is under 18.</p><label>Parent or guardian name<input name="guardian_name" maxlength="190"></label><div class="field-pair"><label>Guardian email<input type="email" name="guardian_email"></label><label>Guardian phone <span>optional</span><input name="guardian_phone" maxlength="40"></label></div></fieldset></div><fieldset class="registration-support-needs"><legend>Participant support needs (optional)</legend><p>Shared only with authorized CTSMD staff coordinating this activity. Please include practical safety or participation information, not diagnoses or unrelated medical history.</p><label>Allergies or sensitivities<textarea name="allergy_information" maxlength="2000" rows="3" placeholder="List any allergies and practical precautions, or leave blank."></textarea></label><label>Accommodations or accessibility needs<textarea name="accommodation_information" maxlength="2000" rows="3" placeholder="Tell us what would help this participant take part, or leave blank."></textarea></label></fieldset><label>Anything staff should know about this registration? <span>optional</span><textarea name="notes" maxlength="2000" rows="4"></textarea><small>Avoid unrelated medical history, diagnoses, or sensitive personal details in these general notes.</small></label><button type="submit"><?=$opportunity['is_full']?'Join waitlist':'Submit registration'?></button></form><?php if($registeredChildren):?><script>(function(){var select=document.getElementById('audition-student-select');var guest=document.getElementById('audition-guest-fields');if(!select||!guest)return;var sync=function(){var known=select.value!=='';guest.hidden=known;guest.querySelectorAll('input,select').forEach(function(control){if(control.name==='participant_first_name'||control.name==='participant_last_name'||control.name==='participant_declared_age'||control.name==='registrant_email'||control.name==='guardian_name'||control.name==='guardian_email'){control.required=!known;}control.disabled=known;});};select.addEventListener('change',sync);sync();})();</script><?php endif;?></section></div>
        <?php else:?><section class="registration-index"><header><small>CTSMD CONNECT</small><h1>Auditions & selected signups</h1><p>This page is intentionally limited. Classes, camps, workshops and the broader CTSMD program catalog continue to use the organization’s existing registration system for now.</p></header><div class="public-grid"><?php if(!$opportunities):?><article class="public-empty"><b>No Connect signups are open right now.</b><p>Check back for auditions and selected special-event or interest signups.</p></article><?php endif;?><?php foreach($opportunities as $o):?><article class="public-card"><small><?=self::e(strtoupper($o['opportunity_type']))?></small><h3><?=self::e($o['title'])?></h3><p><?=self::e((string)($o['summary']?:'Registration is open.'))?></p><?php if($o['starts_at']):?><span><?=self::e(date('M j, Y',strtotime($o['starts_at'])))?></span><?php endif;?><a href="<?=self::u($basePath,'/register?slug='.rawurlencode($o['slug']))?>"><?=$o['is_full']?'Join waitlist':'View & register'?> →</a></article><?php endforeach;?></div></section><?php endif;?></main><?php self::foot();
    }

    private static function manage(PDO $db,string $basePath):never
    {
        $token=(string)($_GET['token']??'');$submission=RegistrationService::submissionForToken($db,$token);$signedIn=Auth::currentUser($db);$claimChildren=($submission&&$signedIn)?AuditionIntakeBridge::eligibleChildren($db,(int)$signedIn['id'],$submission):[];$flash=$_SESSION['public_registration_flash']??null;unset($_SESSION['public_registration_flash']);self::head('Manage registration',$basePath);?><main class="public-shell"><header class="public-header"><a class="public-brand" href="<?=self::u($basePath,'/')?>"><span>C</span><b>CTSMD <small>CONNECT</small></b></a></header><section class="registration-success"><?php if($flash):?><div class="public-flash <?=$flash['type']?>"><?=self::e($flash['message'])?></div><?php endif;?><?php if(!$submission):?><small>REGISTRATION</small><h1>This private link is invalid.</h1><p>Use the manage link from the registration confirmation email.</p><?php else:?><small><?=self::e(strtoupper($submission['status']))?></small><h1><?=self::e($submission['opportunity_title'])?></h1><p><b><?=self::e($submission['participant_first_name'].' '.$submission['participant_last_name'])?></b> · submitted <?=self::e(date('M j, Y',strtotime($submission['submitted_at'])))?></p><?php if(($submission['participant_age_group']??'')!=='adult'&&!in_array($submission['status'],['cancelled','declined'],true)):?><div class="registration-account-link"><?php if(!empty($submission['linked_student_id'])):?><h2>Connected to a CTSMD student</h2><p>This audition has been linked to the participant’s Student profile. If approved, they enter the production’s casting workflow as Under Review. Casting decisions remain private until communicated by CTSMD.</p><?php else:?><h2>Connect this audition to your child</h2><p>Have a CTSMD account? Sign in with the guardian email used on this registration. The child, not the guardian, will be the casting participant.</p><?php if(!$signedIn):?><a href="<?=self::u($basePath,'/login')?>">Sign in to CTSMD Connect</a> · <a href="<?=self::u($basePath,'/join')?>">Create an account</a><p>After signing in, reopen this private registration link from your confirmation email.</p><?php elseif($claimChildren):?><form method="post"><input type="hidden" name="csrf_token" value="<?=self::e((string)$_SESSION['public_registration_csrf'])?>"><input type="hidden" name="token" value="<?=self::e($token)?>"><input type="hidden" name="action" value="claim_audition"><label>Matching child in your household<select name="student_id" required><?php foreach($claimChildren as $child):?><option value="<?=(int)$child['id']?>"><?=self::e($child['name'])?></option><?php endforeach;?></select></label><button type="submit">Link my child's audition</button></form><?php else:?><p>No matching child profile is available in this household. Verify your account and add the child under My family, then reopen this link. CTSMD staff can help if the child already has a profile.</p><?php endif;?><?php endif;?></div><?php endif;?><?php if(!in_array($submission['status'],['cancelled','declined'],true)):?><form method="post" class="cancel-registration"><input type="hidden" name="csrf_token" value="<?=self::e((string)$_SESSION['public_registration_csrf'])?>"><input type="hidden" name="token" value="<?=self::e($token)?>"><button type="submit">Cancel registration</button></form><?php else:?><p>This registration is no longer active.</p><?php endif;?><?php endif;?><a href="<?=self::u($basePath,'/')?>">CTSMD Connect home</a></section></main><?php self::foot();
    }

    private static function head(string $title,string $basePath,?array $brand=null):void
    {
        header('Content-Type:text/html; charset=utf-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="<?=self::e($brand['primary']??'#181416')?>"><title><?=self::e($title)?><?= $brand===null?' · CTSMD':''?></title><link rel="stylesheet" href="<?=self::u($basePath,'/assets/css/public.css')?>"><?php if($brand!==null):?><link rel="stylesheet" href="<?=self::u($basePath,'/assets/css/ux-workspaces.css?v=20261027')?>"><link rel="stylesheet" href="<?=self::u($basePath,'/assets/css/public-home.css?v=20261030-past-hover')?>"><?php endif;?></head><body<?=$brand!==null?' class="ux-workspace public-home"':''?>><?php
    }
    private static function foot():never{?></body></html><?php exit;}
    private static function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
    private static function u(string $base,string $path):string{return ($base?:'').$path;}
    private static function flash(string $type,string $message):void{$_SESSION['public_registration_flash']=['type'=>$type,'message'=>$message];}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
}
